await page.evaluate('async () => {const wait=()=>new Promise(r=>setTimeout(r,60));const btn=(role,name)=>[...document.querySelectorAll(role===\'button\'?\'button\':`[role=${role}]`)].find(b=>(b.getAttribute(\'aria-label\')??b.textContent.trim().replace(/›$/,\'\'))===name);const click=async(role,name)=>{const b=btn(role,name);if(!b)throw Error(\'Missing \'+role+\':\'+name);b.click();await wait();};const tabs=()=>[...document.querySelectorAll(\'[role=tab]\')].map(t=>({name:t.textContent,active:t.getAttribute(\'aria-current\')===\'page\',selected:t.getAttribute(\'aria-selected\')===\'true\'}));await click(\'button\',\'Insert Sheet\');await click(\'button\',\'Insert Sheet\');await click(\'tab\',\'Sheet1\');await click(\'button\',\'Sheet\');await click(\'menuitem\',\'Navigate\');const next=[...document.querySelectorAll(\'[role=menuitem]\')].find(b=>b.getAttribute(\'aria-keyshortcuts\')===\'Ctrl+PAGEDOWN\');if(!next||next.disabled)throw Error(\'Next sheet unavailable\');next.click();await wait();const navigation=tabs();await click(\'button\',\'Edit\');await click(\'menuitem\',\'Select\');await click(\'menuitem\',\'Select to Previous Sheet\');const extended=tabs();await click(\'button\',\'Edit\');await click(\'menuitem\',\'Select\');await click(\'menuitem\',\'Select All Sheets\');const all=tabs();const grid=document.querySelector(\'[role=grid]\');grid.dispatchEvent(new KeyboardEvent(\'keydown\',{key:\'PageUp\',ctrlKey:true,bubbles:true,cancelable:true}));await wait();const wrapped=tabs();grid.dispatchEvent(new KeyboardEvent(\'keydown\',{key:\'PageDown\',metaKey:true,bubbles:true,cancelable:true}));await wait();const returned=tabs();if(!navigation[1].active||!extended[0].selected||!extended[1].selected||!all.every(t=>t.selected)||!wrapped[2].active||wrapped.filter(t=>t.selected).length!==1||!returned[0].active)throw Error(\'Unexpected sheet state\');return {url:location.href,navigation,extended,all,wrapped,returned};}');
